START TRANSACTION;
CREATE TABLE asset."FgsAssetAttribute" (
    "TenantId" bigint NOT NULL,
    "CompanyId" bigint NOT NULL,
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AssetTypeId" bigint NOT NULL,
    "AttributeCode" character varying(75) NOT NULL,
    "AttributeName" character varying(200) NOT NULL,
    "InputType" character varying(25) NOT NULL,
    "DefaultOptionId" bigint,
    "DefaultValueText" character varying(500),
    "DefaultValueInteger" integer,
    "DefaultValueDecimal" numeric(18,4),
    "DefaultValueDate" date,
    "DefaultValueBoolean" boolean,
    "IsRequired" boolean NOT NULL DEFAULT FALSE,
    "IsSearchable" boolean NOT NULL DEFAULT TRUE,
    "DisplayOrder" integer NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
    "CreatedBy" character varying(200),
    "UpdatedOn" timestamptz,
    "UpdatedBy" character varying(200),
    CONSTRAINT "PK_FgsAssetAttribute" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_FgsAssetAttribute_AttributeCode_Upper" CHECK ("AttributeCode" = upper("AttributeCode")),
    CONSTRAINT "CK_FgsAssetAttribute_InputType_Upper" CHECK ("InputType" = upper("InputType")),
    CONSTRAINT "FK_FgsAssetAttribute_AssetType" FOREIGN KEY ("AssetTypeId") REFERENCES asset."FgsAssetType" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FgsAssetAttribute_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES asset."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
);
COMMENT ON TABLE asset."FgsAssetAttribute" IS 'Defines custom asset attributes that can be assigned to specific asset types.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."TenantId" IS 'Tenant identifier.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."CompanyId" IS 'Company identifier.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."Id" IS 'Unique asset attribute identifier.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."AssetTypeId" IS 'Asset type that owns this attribute definition.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."AttributeCode" IS 'Unique attribute code within the asset type. Stored in uppercase.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."AttributeName" IS 'Display name shown to users.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."InputType" IS 'Input type. Valid values: TEXT, TEXTAREA, INTEGER, DECIMAL, DATE, BOOLEAN, DROPDOWN.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultOptionId" IS 'Default dropdown option when InputType is DROPDOWN.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultValueText" IS 'Default text value.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultValueInteger" IS 'Default integer value.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultValueDecimal" IS 'Default decimal value.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultValueDate" IS 'Default date value.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DefaultValueBoolean" IS 'Default boolean value.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."IsRequired" IS 'Indicates whether a value must be supplied when creating or updating an asset.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."IsSearchable" IS 'Indicates whether the attribute should be available in asset search and filtering screens.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."DisplayOrder" IS 'Controls the display order of attributes within the asset type.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."IsActive" IS 'Indicates whether the attribute definition is active.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."CreatedOn" IS 'Date and time the record was created.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."CreatedBy" IS 'User who created the record.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."UpdatedOn" IS 'Date and time the record was last updated.';
COMMENT ON COLUMN asset."FgsAssetAttribute"."UpdatedBy" IS 'User who last updated the record.';

CREATE TABLE asset."FgsAssetWarranty" (
    "TenantId" bigint NOT NULL,
    "CompanyId" bigint NOT NULL,
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AssetId" bigint NOT NULL,
    "WarrantyType" character varying(75) NOT NULL,
    "WarrantyProvider" character varying(200),
    "WarrantyNumber" character varying(100),
    "RegistrationNumber" character varying(100),
    "StartDate" date NOT NULL,
    "EndDate" date NOT NULL,
    "CoverageDescription" character varying(1000),
    "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
    "CreatedBy" character varying(200),
    "UpdatedOn" timestamptz,
    "UpdatedBy" character varying(200),
    CONSTRAINT "PK_FgsAssetWarranty" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_FgsAssetWarranty_DateRange" CHECK ("EndDate" >= "StartDate"),
    CONSTRAINT "CK_FgsAssetWarranty_WarrantyType_Upper" CHECK ("WarrantyType" = upper("WarrantyType")),
    CONSTRAINT "FK_FgsAssetWarranty_Asset" FOREIGN KEY ("AssetId") REFERENCES asset."FgsAsset" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_FgsAssetWarranty_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES asset."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
);
COMMENT ON TABLE asset."FgsAssetWarranty" IS 'Stores warranty coverage associated with customer assets and equipment.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."TenantId" IS 'Tenant identifier.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."CompanyId" IS 'Company identifier.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."Id" IS 'Unique warranty record identifier.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."AssetId" IS 'Asset covered by the warranty.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."WarrantyType" IS 'Warranty type such as MANUFACTURER, MANUFACTURER_EXTENDED, LABOR, LABOR_EXTENDED, PARTS, COMPRESSOR, HEAT_EXCHANGER, INSTALLATION, or OTHER.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."WarrantyProvider" IS 'Manufacturer, contractor, dealer, or third-party organization providing the warranty coverage.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."WarrantyNumber" IS 'Warranty contract number, policy number, or manufacturer warranty identifier.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."RegistrationNumber" IS 'Warranty registration confirmation number provided by the warranty issuer.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."StartDate" IS 'Date warranty coverage becomes effective.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."EndDate" IS 'Date warranty coverage expires.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."CoverageDescription" IS 'Detailed description of warranty coverage including covered components, labor coverage, exclusions, reimbursement limitations, registration requirements, and special warranty terms.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."CreatedOn" IS 'Date and time the record was created.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."CreatedBy" IS 'User who created the record.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."UpdatedOn" IS 'Date and time the record was last updated.';
COMMENT ON COLUMN asset."FgsAssetWarranty"."UpdatedBy" IS 'User who last updated the record.';

CREATE TABLE asset."FgsAssetAttributeOption" (
    "TenantId" bigint NOT NULL,
    "CompanyId" bigint NOT NULL,
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AssetAttributeId" bigint NOT NULL,
    "OptionCode" character varying(75) NOT NULL,
    "OptionName" character varying(200) NOT NULL,
    "DisplayOrder" integer NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
    "CreatedBy" character varying(200),
    "UpdatedOn" timestamptz,
    "UpdatedBy" character varying(200),
    CONSTRAINT "PK_FgsAssetAttributeOption" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_FgsAssetAttributeOption_OptionCode_Upper" CHECK ("OptionCode" = upper("OptionCode")),
    CONSTRAINT "FK_FgsAssetAttributeOption_AssetAttribute" FOREIGN KEY ("AssetAttributeId") REFERENCES asset."FgsAssetAttribute" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_FgsAssetAttributeOption_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES asset."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
);
COMMENT ON TABLE asset."FgsAssetAttributeOption" IS 'Stores selectable dropdown values for asset attributes.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."TenantId" IS 'Tenant identifier.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."CompanyId" IS 'Company identifier.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."Id" IS 'Unique asset attribute option identifier.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."AssetAttributeId" IS 'Asset attribute definition that owns this option.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."OptionCode" IS 'Unique option code within the asset attribute. Stored in uppercase.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."OptionName" IS 'Display name shown to users.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."DisplayOrder" IS 'Controls the order in which options are displayed to users.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."IsActive" IS 'Indicates whether the option is available for selection on new or updated assets.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."CreatedOn" IS 'Date and time the record was created.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."CreatedBy" IS 'User who created the record.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."UpdatedOn" IS 'Date and time the record was last updated.';
COMMENT ON COLUMN asset."FgsAssetAttributeOption"."UpdatedBy" IS 'User who last updated the record.';

